{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e6-cascade-share-t5/cell-5sgpFt/src/address.js","content":"/**
 * Cell addresses. A valid address is one or two letters naming a column and
 * one to three digits naming a row of at least 1, read case-insensitively.
 */

const ADDRESS = /^([A-Za-z]{1,2})([0-9]{1,3})$/

/** Parse a word into `{ col, row }`, or null when it is out of range. */
export function parseAddress(word) {
  const m = ADDRESS.exec(word)
  if (m === null) return null
  const letters = m[1].toUpperCase()
  let col = 0
  for (const ch of letters) col = col * 26 + (ch.charCodeAt(0) - 64)
  const row = Number(m[2])
  if (row < 1) return null
  return { col, row }
}

/** The canonical text of a column number: 1 is `A` and 27 is `AA`. */
export function columnName(col) {
  let name = ''
  let n = col
  while (n > 0) {
    const rem = (n - 1) % 26
    name = String.fromCharCode(65 + rem) + name
    n = (n - rem - 1) / 26
  }
  return name
}

/** The canonical text of an address. */
export function formatAddress(cell) {
  return columnName(cell.col) + String(cell.row)
}

/** A sort key placing cells in column order and then in row order. */
export function addressKey(cell) {
  return cell.col * 1000 + cell.row
}

/** Every address a range covers, in column and then row order. */
export function expandRange(a, b) {
  const c0 = Math.min(a.col, b.col)
  const c1 = Math.max(a.col, b.col)
  const r0 = Math.min(a.row, b.row)
  const r1 = Math.max(a.row, b.row)
  const cells = []
  for (let col = c0; col <= c1; col++) {
    for (let row = r0; row <= r1; row++) cells.push({ col, row })
  }
  return cells
}
"}

