 * Values: a number, text, a boolean, or an error.
 */

export const DIV0 = '#DIV/0!'
export const REF = '#REF!'
export const VALUE = '#VALUE!'
export const CYCLE = '#CYCLE!'
export const NAME = '#NAME?'
export const ERR = '#ERR!'

export const ERROR_TOKENS = [DIV0, REF, VALUE, CYCLE, NAME, ERR]

export const num = (n) => ({ kind: 'number', number: n })
export const text = (s) => ({ kind: 'text', text: s })
export const bool = (b) => ({ kind: 'boolean', boolean: b })
export const err = (token) => ({ kind: 'error', error: token })

export const ZERO = num(0)
export const isError = (value) => value.kind === 'error'

/** A number that is not finite is the division error. */
export function finite(n) {
  return Number.isFinite(n) ? num(n) : err(DIV0)
}

/** A value in an arithmetic position: text fails, a boolean is 1 or 0. */
export function toNumber(value) {
  if (value.kind === 'number') return value
  if (value.kind === 'boolean') return num(value.boolean ? 1 : 0)
  if (value.kind === 'error') return value
  return err(VALUE)
}

const KIND_ORDER = { number: 0, text: 1, boolean: 2 }

function compareText(a, b) {
  const x = [...a]
  const y = [...b]
  const n = Math.min(x.length, y.length)
  for (let i = 0; i < n; i++) {
    const ca = x[i].codePointAt(0)
    const cb = y[i].codePointAt(0)
    if (ca !== cb) return ca < cb ? -1 : 1
  }
  if (x.length === y.length) return 0
  return x.length < y.length ? -1 : 1
}

/** Order two values: numbers below text below booleans. */
export function compareValues(a, b) {
  const ka = KIND_ORDER[a.kind]
  const kb = KIND_ORDER[b.kind]
  if (ka !== kb) return ka < kb ? -1 : 1
  if (a.kind === 'number') {
    if (a.number === b.number) return 0
    return a.number < b.number ? -1 : 1
  }
  if (a.kind === 'text') return compareText(a.text, b.text)
  const x = a.boolean ? 1 : 0
  const y = b.boolean ? 1 : 0
  return x === y ? 0 : x < y ? -1 : 1
}

/** Print a number as JavaScript would after rounding to ten significant digits. */
export function formatNumber(n) {
  if (!Number.isFinite(n)) return String(n)
  const rounded = Number(n.toPrecision(10))
  if (rounded === 0) return '0'
  return String(rounded)
}

/** Print a value as the `values` mode does. */
export function formatValue(value) {
  switch (value.kind) {
    case 'number':
      return formatNumber(value.number)
    case 'text':
      return value.text
    case 'boolean':
      return value.boolean ? 'TRUE' : 'FALSE'
    default:
      return value.error
  }
}
"}

