{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e6-cascade-share-t5/cell-5sgpFt/src/formula.js","content":"/**
 * The formula grammar. `parseFormula` returns a tree, or null when the body is
 * not something the grammar accepts.
 */

const DIGIT = /[0-9]/
const LETTER = /[A-Za-z]/

/** Split a formula body into tokens, or null when a character has no token. */
function tokenize(body) {
  const tokens = []
  let i = 0
  while (i < body.length) {
    const ch = body[i]
    if (ch === ' ' || ch === '\t') {
      i++
    } else if (DIGIT.test(ch)) {
      let j = i
      while (j < body.length && DIGIT.test(body[j])) j++
      if (body[j] === '.' && j + 1 < body.length && DIGIT.test(body[j + 1])) {
        j++
        while (j < body.length && DIGIT.test(body[j])) j++
      }
      tokens.push({ type: 'number', text: body.slice(i, j) })
      i = j
    } else if (LETTER.test(ch)) {
      let j = i
      while (j < body.length && LETTER.test(body[j])) j++
      while (j < body.length && DIGIT.test(body[j])) j++
      tokens.push({ type: 'word', text: body.slice(i, j) })
      i = j
    } else if (ch === '(' || ch === ')' || ch === ',' || ch === ':') {
      const type = ch === '(' ? 'open' : ch === ')' ? 'close' : ch === ',' ? 'comma' : 'colon'
      tokens.push({ type, text: ch })
      i++
    } else if (ch === '<') {
      if (body[i + 1] === '>' || body[i + 1] === '=') {
        tokens.push({ type: 'op', text: body.slice(i, i + 2) })
        i += 2
      } else {
        tokens.push({ type: 'op', text: '<' })
        i++
      }
    } else if (ch === '>') {
      if (body[i + 1] === '=') {
        tokens.push({ type: 'op', text: '>=' })
        i += 2
      } else {
        tokens.push({ type: 'op', text: '>' })
        i++
      }
    } else if ('^*/+-='.includes(ch)) {
      tokens.push({ type: 'op', text: ch })
      i++
    } else {
      return null
    }
  }
  return tokens
}

const COMPARISONS = new Set(['=', '<>', '<', '<=', '>', '>='])

class Failure extends Error {}

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.at = 0
  }

  peek() {
    return this.at < this.tokens.length ? this.tokens[this.at] : null
  }

  next() {
    const token = this.peek()
    if (token === null) throw new Failure()
    this.at++
    return token
  }

  eat(type, text) {
    const token = this.peek()
    if (token === null || token.type !== type) return false
    if (text !== undefined && token.text !== text) return false
    this.at++
    return true
  }

  expect(type) {
    const token = this.next()
    if (token.type !== type) throw new Failure()
    return token
  }

  isOperator(set) {
    const token = this.peek()
    return token !== null && token.type === 'op' && set.has(token.text)
  }

  parseExpression() {
    return this.parseComparison()
  }

  parseComparison() {
    let left = this.parseAdditive()
    while (this.isOperator(COMPARISONS)) {
      const op = this.next().text
      const right = this.parseAdditive()
      left = { type: 'binary', op, left, right }
    }
    return left
  }

  parseAdditive() {
    let left = this.parseMultiplicative()
    while (this.isOperator(ADDITIVE)) {
      const op = this.next().text
      const right = this.parseMultiplicative()
      left = { type: 'binary', op, left, right }
    }
    return left
  }

  parseMultiplicative() {
    let left = this.parsePower()
    while (this.isOperator(MULTIPLICATIVE)) {
      const op = this.next().text
      const right = this.parsePower()
      left = { type: 'binary', op, left, right }
