{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e6-cascade-share-t5/cell-5sgpFt/src/sheet.js","content":"/**
 * Reading a sheet: one declaration to a line, an address and then the content.
 */

import { parseAddress, formatAddress, addressKey } from './address.js'
import { parseFormula } from './formula.js'
import { num, text, err, ZERO, ERROR_TOKENS } from './value.js'

/** A failure that stops the program with its message on standard error. */
export class SheetError extends Error {}

const NUMBER = /^-?[0-9]+(\.[0-9]+)?$/

/** The value of content that is not a formula. */
export function literalValue(content) {
  if (content === '') return ZERO
  if (NUMBER.test(content)) return num(Number(content))
  if (ERROR_TOKENS.includes(content)) return err(content)
  return text(content)
}

function isBlank(ch) {
  return ch === ' ' || ch === '\t'
}

/** Split the sheet into its declared cells, in column and then row order. */
export function parseSheet(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const declared = new Map()
  for (let index = 0; index < lines.length; index++) {
    const lineNumber = index + 1
    let line = lines[index]
    let start = 0
    while (start < line.length && isBlank(line[start])) start++
    line = line.slice(start)
    if (line === '' || line[0] === '#') continue

    let end = 0
    while (end < line.length && !isBlank(line[end])) end++
    const word = line.slice(0, end)
    let rest = line.slice(end)
    let gap = 0
    while (gap < rest.length && isBlank(rest[gap])) gap++
    const content = rest.slice(gap)

    const cell = parseAddress(word)
    if (cell === null) {
      throw new SheetError(`error: line ${lineNumber}: invalid cell address ${word}`)
    }
    const address = formatAddress(cell)
    if (declared.has(address)) {
      throw new SheetError(`error: line ${lineNumber}: cell ${address} is declared twice`)
    }
    declared.set(address, {
      address,
      cell,
      content,
      formula: content.startsWith('=') ? parseFormula(content.slice(1)) : undefined,
      isFormula: content.startsWith('='),
    })
  }

  const cells = [...declared.values()]
  cells.sort((a, b) => addressKey(a.cell) - addressKey(b.cell))
  return { cells, byAddress: declared }
}
"}

