/**
 * The command. `node src/cli.js values` prints the value of every cell in the
 * sheet read from standard input, and `node src/cli.js deps` prints the cells
 * each one reads.
 */

import { readFileSync } from 'node:fs'
import { parseSheet, SheetError } from './sheet.js'
import { Evaluator, dependencies } from './evaluate.js'
import { formatValue } from './value.js'

function fail(message) {
  process.stderr.write(message + '\n')
  process.exit(2)
}

function readInput() {
  try {
    return readFileSync(0, 'utf8')
  } catch {
    return ''
  }
}

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'values' && mode !== 'deps')) {
    fail('error: usage: cli.js values|deps')
  }

  let sheet
  try {
    sheet = parseSheet(readInput())
  } catch (error) {
    if (error instanceof SheetError) fail(error.message)
    throw error
  }

  const lines = []
  if (mode === 'values') {
    const evaluator = new Evaluator(sheet)
    for (const cell of sheet.cells) {
      lines.push(`${cell.address}=${formatValue(evaluator.valueAt(cell.address))}`)
    }
  } else {
    for (const cell of sheet.cells) {
      const names = dependencies(cell)
      lines.push(`${cell.address}:${names.map((name) => ' ' + name).join('')}`)
    }
  }
  if (lines.length > 0) process.stdout.write(lines.join('\n') + '\n')
}

main(process.argv.slice(2))
"}

